19	public interface OwnerMapper {
20	
21	    @Mapping(target = "displayName", expression = "java(formatDisplayName(owner))")
22	    @Mapping(target = "initials", expression = "java(formatInitials(owner))")
23	    @Mapping(target = "membershipNumber", expression = "java(formatMembershipNumber(owner))")
