28	    @Mapping(target = "bulkSignupWarning", ignore = true)
29	    OwnerDto toOwnerDto(Owner owner);
30	
31	    /**
32	     * Derives an owner's duplicate-detection identity key as
33	     * {@code '<normalizedTelephone>|<email or empty>|<householdId or empty>'} from the stored
34	     * (already E.164-normalized) telephone, lower-cased email and household id. A {@code null}
35	     * telephone, email or household id contributes the empty string in its position.
36	     */
37	    default String formatIdentityKey(Owner owner) {
38	        if (owner == null) {
39	            return null;
40	        }
41	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
42	        String email = owner.getEmail() == null ? "" : owner.getEmail().toLowerCase();
43	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
44	        return telephone + "|" + email + "|" + householdId;
45	    }
46	
47	    /**
48	     * Derives an owner's preferred contact channel: {@code EMAIL} when an email address is present
49	     * (non-null and non-blank), otherwise {@code PHONE}.
50	     */
51	    default OwnerDto.ContactPreferenceEnum formatContactPreference(Owner owner) {
52	        if (owner == null) {
53	            return null;
54	        }
55	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
56	        return hasEmail ? OwnerDto.ContactPreferenceEnum.EMAIL : OwnerDto.ContactPreferenceEnum.PHONE;
57	    }
58	
59	    /**
60	     * Derives an owner's locality (region) preferring the postcode: the region is resolved by
61	     * postcode range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), and only when the
62	     * postcode is absent or in no known range does it fall back to the fixed city-to-region table
63	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns
64	     * {@code "UNKNOWN"} when neither the postcode nor the city resolves to a region.
65	     */
66	    default String formatLocality(Owner owner) {
67	        if (owner == null) {
68	            return null;
69	        }
70	        String fromPostcode = regionForPostcode(owner.getPostcode());
71	        if (fromPostcode != null) {
72	            return fromPostcode;
73	        }
74	        return switch (owner.getCity() == null ? "" : owner.getCity()) {
75	            case "Sydney" -> "NSW";
76	            case "Melbourne" -> "VIC";
77	            case "Brisbane" -> "QLD";
78	            default -> "UNKNOWN";
79	        };
80	    }
81	
82	    /**
83	     * Resolves a region from a 4-digit postcode by inclusive range (NSW 2000-2099, VIC 3000-3099,
84	     * QLD 4000-4099). Returns {@code null} when the postcode is absent, not exactly 4 digits, or in
85	     * no known range, signalling that the caller should fall back to the city-to-region table.
86	     */
87	    private String regionForPostcode(String postcode) {
88	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
89	            return null;
90	        }
91	        int value = Integer.parseInt(postcode);
92	        if (value >= 2000 && value <= 2099) {
93	            return "NSW";
94	        }
95	        if (value >= 3000 && value <= 3099) {
96	            return "VIC";
97	        }
98	        if (value >= 4000 && value <= 4099) {
99	            return "QLD";
100	        }
101	        return null;
102	    }
103	
104	    /**
105	     * Computes an owner's membership level, a number from 1 to 3: starting at 1, plus 1 when an email
106	     * is present, plus 1 when the owner's namesake count is 0, capped at 3 (level 4 is reserved for
107	     * tenure).
108	     */
109	    default Integer formatMembershipLevel(Owner owner) {
110	        if (owner == null) {
111	            return null;
112	        }
113	        int level = 1;
114	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
115	        if (hasEmail) {
116	            level++;
117	        }
118	        boolean unique = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
119	        if (unique) {
120	            level++;
121	        }
122	        return Math.min(level, 3);
123	    }
124	
125	    /**
126	     * Formats an owner's membership number as {@code '<customerCode>-M<YY>'}, where YY is the last two
127	     * digits of the registration-date year (e.g. {@code "LON-SMI-0007-M26"}). Returns {@code null} when the
128	     * customer code or registration date is absent.
129	     */
130	    default String formatMembershipNumber(Owner owner) {
131	        if (owner == null || owner.getCustomerCode() == null || owner.getRegistrationDate() == null) {
132	            return null;
133	        }
134	        return String.format("%s-M%02d", owner.getCustomerCode(), owner.getRegistrationDate().getYear() % 100);
135	    }
136	
137	    /**
138	     * Formats an owner's display name as {@code "LastName, FirstName"} from the stored names.
139	     */
140	    default String formatDisplayName(Owner owner) {
141	        if (owner == null) {
142	            return null;
143	        }
144	        return owner.getLastName() + ", " + owner.getFirstName();
145	    }
146	
147	    /**
148	     * Formats an owner's initials as the upper-cased first letters of the first and last
149	     * names, dot-separated with a trailing dot (e.g. {@code "J.S."}).
150	     */
151	    default String formatInitials(Owner owner) {
152	        if (owner == null) {
153	            return null;
154	        }
155	        return initial(owner.getFirstName()) + initial(owner.getLastName());
156	    }
157	
158	    private String initial(String name) {
159	        if (name == null || name.isEmpty()) {
160	            return "";
161	        }
162	        return Character.toUpperCase(name.charAt(0)) + ".";
163	    }
